using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    [ColumnName("Label")]
    public string Category { get; set; } = string.Empty;
}

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

public class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

public class PredictionResponse
{
    public string PredictedCategory { get; set; } = string.Empty;
    public Dictionary<string, float> ConfidenceScores { get; set; } = new();
}

public class EvaluationResponse
{
    public float MacroAccuracy { get; set; }
    public float MicroAccuracy { get; set; }
    public float LogLoss { get; set; }
    public float LogLossReduction { get; set; }
    public List<CategoryMetric> PerCategoryMetrics { get; set; } = new();
}

public class CategoryMetric
{
    public string Category { get; set; } = string.Empty;
    public double Precision { get; set; }
    public double Recall { get; set; }
    public double F1Score { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly IDataView _trainingData;
    private readonly string[] _categoryNames;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 42);
        _trainingData = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        _model = TrainModel();
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract ordered label names from the model's key-value mapping
        var schema = _model.GetOutputSchema(_trainingData.Schema);
        var labelColumn = schema["PredictedLabel"];
        var keyValues = new VBuffer<ReadOnlyMemory<char>>();
        labelColumn.GetKeyValues(ref keyValues);
        _categoryNames = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
    }

    private ITransformer TrainModel()
    {
        // Combine Subject + Description into a single text feature, include Priority
        var pipeline = _mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        return pipeline.Fit(_trainingData);
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var confidenceScores = new Dictionary<string, float>();
        for (int i = 0; i < _categoryNames.Length; i++)
        {
            confidenceScores[_categoryNames[i]] = prediction.Score[i];
        }

        return new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            ConfidenceScores = confidenceScores
        };
    }

    public EvaluationResponse Evaluate()
    {
        // Cross-validate since the dataset is small
        var crossValidationResults = _mlContext.MulticlassClassification
            .CrossValidate(_trainingData, BuildPipeline(), numberOfFolds: 3);

        var avgMacroAccuracy = crossValidationResults.Average(r => r.Metrics.MacroAccuracy);
        var avgMicroAccuracy = crossValidationResults.Average(r => r.Metrics.MicroAccuracy);
        var avgLogLoss = crossValidationResults.Average(r => r.Metrics.LogLoss);
        var avgLogLossReduction = crossValidationResults.Average(r => r.Metrics.LogLossReduction);

        // Evaluate on training data for per-category metrics
        var predictions = _model.Transform(_trainingData);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        var perCategory = new List<CategoryMetric>();
        for (int i = 0; i < metrics.PerClassLogLoss.Count; i++)
        {
            var name = i < _categoryNames.Length ? _categoryNames[i] : $"Class_{i}";
            perCategory.Add(new CategoryMetric
            {
                Category = name,
                Precision = metrics.ConfusionMatrix.PerClassPrecision[i],
                Recall = metrics.ConfusionMatrix.PerClassRecall[i],
                F1Score = 2 * (metrics.ConfusionMatrix.PerClassPrecision[i] * metrics.ConfusionMatrix.PerClassRecall[i])
                    / (metrics.ConfusionMatrix.PerClassPrecision[i] + metrics.ConfusionMatrix.PerClassRecall[i])
            });
        }

        return new EvaluationResponse
        {
            MacroAccuracy = (float)avgMacroAccuracy,
            MicroAccuracy = (float)avgMicroAccuracy,
            LogLoss = (float)avgLogLoss,
            LogLossReduction = (float)avgLogLossReduction,
            PerCategoryMetrics = perCategory
        };
    }

    private IEstimator<ITransformer> BuildPipeline()
    {
        return _mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy())
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
    }
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketController : ControllerBase
{
    private readonly TicketClassifierService _classifierService;

    public TicketController(TicketClassifierService classifierService)
    {
        _classifierService = classifierService;
    }

    [HttpPost("classify")]
    public ActionResult<PredictionResponse> Classify([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject or Description is required.");

        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        var result = _classifierService.Predict(request);
        return Ok(result);
    }

    [HttpGet("evaluate")]
    public ActionResult<EvaluationResponse> Evaluate()
    {
        var result = _classifierService.Evaluate();
        return Ok(result);
    }
}

