1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using TicketClassifier.Models;
4. 
5. namespace TicketClassifier.Services;
6. 
7. public class TicketClassifierService
8. {
9.     private readonly MLContext _mlContext;
10.     private readonly ITransformer _model;
11.     private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
12.     private readonly IDataView _trainingData;
13.     private readonly string[] _categoryNames;
14. 
15.     public TicketClassifierService(string dataPath)
16.     {
17.         _mlContext = new MLContext(seed: 42);
18.         _trainingData = _mlContext.Data.LoadFromTextFile<TicketData>(
19.             dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
20. 
21.         _model = TrainModel();
22.         _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
23. 
24.         // Extract ordered label names from the model's key-value mapping
25.         var schema = _model.GetOutputSchema(_trainingData.Schema);
26.         var labelColumn = schema["PredictedLabel"];
27.         var keyValues = new VBuffer<ReadOnlyMemory<char>>();
28.         labelColumn.Annotations.GetValue("KeyValues", ref keyValues);
29.         _categoryNames = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
30.     }
31. 
32.     private ITransformer TrainModel()
33.     {
